use std::quantum::{h,z,init0}; use std::observe::measure_z;
        unitary fn inverse(q:Q<Bit>)->Q<Bit>{q}
        unitary fn oracle(q:Q<Bit>)->Q<Bit>{z(q)}
        unitary fn undo(q:Q<Bit>)->Q<Bit>{inverse(oracle)(q)}
        pub observe fn main()->Bit{measure_z(h(undo(inverse(h(init0())))))}
